// tsconfig.json
{
  "compilerOptions": {
    "strict": true,
    "noEmit": true,
    "target": "ES2022",
    "module": "nodenext"
  },
  "include": ["*.ts"]
}

// price.ts
type Item = { name: string; price: number };

function total(items: Item[]): number {
  return items.reduce((sum, i) => sum + i.price, 0);
}

console.log(total([{ name: "чай", price: "100" }]));

npx tsc --noEmit
